import re

with open('/app/schedule.txt', 'r', encoding='utf-8') as f:
    lines = f.readlines()

# Build section map: for each line, what section does it belong to?
section_starts = []
for i, line in enumerate(lines):
    # Only track 通识核心 headers at the start of a block (not at the very beginning of a line with content)
    raw = line.strip()
    # Headers typically appear alone on their line or with minimal content
    if '通识教育核心课程——七大模块课程' in raw and raw.count('通识教育核心课程') == 1 and '模块' in raw:
        section_starts.append((i, '通识核心'))
    elif '通识教育核心课程——公共艺术课程' in raw:
        section_starts.append((i, '通识核心'))
    elif '通识教育核心课程——思想政治理论课程A组' in raw:
        section_starts.append((i, '思政A'))
    elif '通识教育核心课程——思想政治理论课程B组' in raw:
        section_starts.append((i, '思政B'))
    elif '通识教育核心课程——形势与政策类课程' in raw:
        section_starts.append((i, '形势与政策'))
    elif '通识教育专项教育课程——' in raw and '第' not in raw.split('通识')[0][-5:]:
        # But not table of contents lines
        if '第' not in raw or raw.find('第') > raw.rfind('通识'):
            section_starts.append((i, '通识专项'))
    elif '基础课程和专业课程' in raw:
        section_starts.append((i, '专业'))
    elif '公共选修课程' in raw and '大类' not in raw:
        section_starts.append((i, '公选'))

# Build section map
section_map = {}
current_sec = '未知'
for sh_line, sh_name in section_starts:
    current_sec = sh_name
    for j in range(sh_line, min(sh_line + 10, len(lines))):
        section_map[j] = current_sec

# For courses, find section by looking backward
for i, line in enumerate(lines):
    if i not in section_map and i > 0:
        for j in range(i-1, -1, -1):
            if j in section_map:
                section_map[i] = section_map[j]
                break
        else:
            section_map[i] = '未知'

# Now find all Monday 开卷 courses in 通识核心 section
def get_course_fields_from_line(line):
    m = re.match(r'^\s*([A-Z]{2,6}\d{6}\.\d+)\s+(.+?)\s+(\d+)\s', line)
    if not m:
        return None
    cid = m.group(1)
    rest = m.group(2)
    credits = m.group(3)

    # Get name - between cid and credits, but there might be multi-word name
    name_m = re.search(r'^\s*([A-Z]{2,6}\d{6}\.\d+)\s+(.+?)\s+(\d+)\s', line)
    name = ''
    if name_m:
        name = name_m.group(2).strip()
        # Clean up - remove extra numbers and whitespace
        name = re.sub(r'\s*\d+\s*', ' ', name).strip()
        name = re.sub(r'\s{2,}', ' ', name).strip()

    wm = re.search(r'([一二三四五六])\s+(\d+-\d+)\s+(\[[^\]]+\])', line)
    weekday = wm.group(1) if wm else ''
    time_range = wm.group(2) if wm else ''
    weeks = wm.group(3) if wm else ''

    campus_m = re.search(r'(邯郸校区|江湾校区|张江校区|枫林校区)', line)
    campus = campus_m.group(1) if campus_m else ''

    exam_type = ''
    for t in ['开卷', '闭卷', '论文', '其他', '半开卷']:
        if t in line:
            exam_type = t
            break

    # Teacher
    t_m = re.search(r'(教授|副教授|讲师|研究员|副研究员|高级工程师|青年研究员|助理研究员)', line)
    teacher = ''
    if t_m:
        teacher = line[:t_m.start()].strip()
        teacher = re.sub(r'^[A-Z]{2,6}\d{6}\.\d+\s+', '', teacher)
        teacher = re.sub(r'\s+\d+\s+', ' ', teacher).strip()

    # Department
    dept_keywords = ['马克思主义学院', '哲学学院', '中国语言文学系', '文学院',
                     '历史学系', '文物与博物馆学系', '国际文化交流学院',
                     '计算机科学技术学院', '软件学院', '信息科学与工程学院', '航空航天系',
                     '政治学', '法学院', '艺术学院', '经济', '管理学院',
                     '生命科学学院', '环境科学', '物理学系', '化学系', '数学科学',
                     '大气', '相辉', '新闻', '社会发展', '社会学', '公共管理',
                     '外国语言', '艺术教育中心', '体育学院', '心理咨询', '大学外语',
                     '环境科学与工程系', '音乐', '舞蹈', '戏剧', '书法',
                     '国际关系与', '社会学系', '公共管理系', '中外法律', '传播学',
                     '文物与考古', '留学生', '管理科学']
    department = ''
    for dk in dept_keywords:
        if dk in line:
            di = line.rfind(dk)
            department = line[di:].strip()
            break

    return {'cid': cid, 'name': name, 'credits': credits, 'teacher': teacher,
            'weekday': weekday, 'time': time_range, 'weeks': weeks,
            'campus': campus, 'exam_type': exam_type, 'department': department}

print('=== 通识核心 Monday 开卷 courses ===')
tongshi_monday_kj = []
for i, line in enumerate(lines):
    if i not in section_map:
        continue
    if section_map[i] != '通识核心':
        continue

    fields = get_course_fields_from_line(line)
    if not fields:
        continue
    if fields['weekday'] == '一' and fields['exam_type'] == '开卷':
        print(f"  {fields['cid']}: {fields['name']}, {fields['credits']}学分, {fields['teacher']}, {fields['weekday']}{fields['time']} {fields['weeks']}, {fields['campus']}, {fields['exam_type']}, {fields['department']}")
        tongshi_monday_kj.append(fields)

print(f'\nTotal: {len(tongshi_monday_kj)}')

# Also get 思政B Monday 开卷
print('\n=== 思政B Monday 开卷 ===')
for i, line in enumerate(lines):
    if i not in section_map:
        continue
    if section_map[i] != '思政B':
        continue
    fields = get_course_fields_from_line(line)
    if not fields:
        continue
    if fields['weekday'] == '一' and fields['exam_type'] == '开卷':
        print(f"  {fields['cid']}: {fields['name']}, {fields['credits']}学分, {fields['teacher']}, {fields['weekday']}{fields['time']} {fields['weeks']}, {fields['campus']}, {fields['exam_type']}, {fields['department']}")

# Check section_map for some lines
print('\n=== Section map for key lines ===')
for line_num in [1245, 1430, 1742, 1844, 1027, 1112, 1614, 1831]:
    if line_num in section_map:
        print(f'  Line {line_num}: {section_map[line_num]}')
    else:
        # Find backward
        for j in range(line_num-1, max(line_num-100, -1), -1):
            if j in section_map:
                print(f'  Line {line_num}: {section_map[j]} (via line {j})')
                break
